import{_ as o,i as e,o as r,an as t}from"./chunks/framework.gCvoxH98.js";const p=JSON.parse('{"title":"术语表","description":"Dora Pocket 文档系统中的核心术语、AI 模型名称和文档类型分类的权威定义。","frontmatter":{"title":"术语表","description":"Dora Pocket 文档系统中的核心术语、AI 模型名称和文档类型分类的权威定义。"},"headers":[],"relativePath":"contributing/documentation/glossary.md","filePath":"contributing/documentation/glossary.md","lastUpdated":1764773245000}'),a={name:"contributing/documentation/glossary.md"};function l(s,i,n,d,g,c){return r(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to “术语表”">​</a></h1><p>本文档定义了 <code>Dora Pocket</code> 文档系统中使用的核心术语、命名规范和分类标准。所有文档编写者和贡献者都应遵循这些定义，以确保项目文档的一致性和专业性。</p><h2 id="ai-模型" tabindex="-1">AI 模型 <a class="header-anchor" href="#ai-模型" aria-label="Permalink to “AI 模型”">​</a></h2><p>本项目使用三种 AI 模型来辅助文档生成和代码开发，每种模型都有其特定的用途和优势。</p><h3 id="codex" tabindex="-1">Codex <a class="header-anchor" href="#codex" aria-label="Permalink to “Codex”">​</a></h3><ul><li><strong>模型标识</strong>: <code>gpt-5.1-codex</code></li><li><strong>用途</strong>: 代码实现、自动化开发、代码生成</li><li><strong>特点</strong>: 擅长理解代码上下文并生成高质量的实现代码</li><li><strong>典型场景</strong>: 功能实现、组件开发、测试用例生成</li></ul><h3 id="gemini" tabindex="-1">Gemini <a class="header-anchor" href="#gemini" aria-label="Permalink to “Gemini”">​</a></h3><ul><li><strong>模型标识</strong>: <code>gemini-2.5-pro</code></li><li><strong>用途</strong>: 代码分析、文档生成、代码审查</li><li><strong>特点</strong>: 拥有强大的分析能力和大型上下文窗口</li><li><strong>典型场景</strong>: 架构分析、文档撰写、模式识别</li></ul><h3 id="qwen" tabindex="-1">Qwen <a class="header-anchor" href="#qwen" aria-label="Permalink to “Qwen”">​</a></h3><ul><li><strong>模型标识</strong>: <code>qwen-coder</code></li><li><strong>用途</strong>: Gemini 的备选方案，分析和文档生成</li><li><strong>特点</strong>: 提供可靠的备份能力，确保服务连续性</li><li><strong>典型场景</strong>: 当 Gemini 不可用时的替代选择</li></ul><h2 id="文档类型" tabindex="-1">文档类型 <a class="header-anchor" href="#文档类型" aria-label="Permalink to “文档类型”">​</a></h2><p><code>Dora Pocket</code> 文档按照内容性质和目标受众分为五个主要类型，每种类型都有其特定的写作风格和结构要求。</p><h3 id="api-文档" tabindex="-1">API 文档 <a class="header-anchor" href="#api-文档" aria-label="Permalink to “API 文档”">​</a></h3><ul><li><strong>定义</strong>: 详细描述函数、类、接口等编程接口的技术文档</li><li><strong>特征</strong>: 包含签名、参数、返回值、示例代码和边界情况</li><li><strong>目标受众</strong>: 使用该 API 的开发者</li><li><strong>典型文件</strong>: <code>@esdora/kit</code> 函数文档、<code>@esdora/color</code> 函数文档</li><li><strong>模板</strong>: <a href="./api-template">API 文档模板</a></li></ul><h3 id="架构文档" tabindex="-1">架构文档 <a class="header-anchor" href="#架构文档" aria-label="Permalink to “架构文档”">​</a></h3><ul><li><strong>定义</strong>: 阐述系统设计、技术选型和架构决策的文档</li><li><strong>特征</strong>: 包含架构图、组件关系、数据流和设计原则</li><li><strong>目标受众</strong>: 系统维护者、架构师、高级开发者</li><li><strong>典型文件</strong>: <code>ARCHITECTURE.md</code>、模块设计文档</li></ul><h3 id="用户指南" tabindex="-1">用户指南 <a class="header-anchor" href="#用户指南" aria-label="Permalink to “用户指南”">​</a></h3><ul><li><strong>定义</strong>: 面向最终用户的使用说明和操作手册</li><li><strong>特征</strong>: 侧重于&quot;如何做&quot;，包含步骤说明和实用示例</li><li><strong>目标受众</strong>: 项目使用者、初学者</li><li><strong>典型文件</strong>: 快速上手、安装指南、常见问题解答</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to “最佳实践”">​</a></h3><ul><li><strong>定义</strong>: 总结经验教训和推荐做法的深度文章</li><li><strong>特征</strong>: 采用&quot;问题-原则-方案&quot;结构，侧重思想和模式传递</li><li><strong>目标受众</strong>: 追求代码质量和工程效率的开发者</li><li><strong>典型文件</strong>: 设计模式、代码规范、性能优化指南</li></ul><h3 id="贡献指南" tabindex="-1">贡献指南 <a class="header-anchor" href="#贡献指南" aria-label="Permalink to “贡献指南”">​</a></h3><ul><li><strong>定义</strong>: 指导外部贡献者参与项目的规范文档</li><li><strong>特征</strong>: 包含工作流程、规范要求和协作指南</li><li><strong>目标受众</strong>: 项目贡献者、开源社区成员</li><li><strong>典型文件</strong>: <code>CONTRIBUTING.md</code>、提交规范、文档编写指南</li></ul><h2 id="核心术语" tabindex="-1">核心术语 <a class="header-anchor" href="#核心术语" aria-label="Permalink to “核心术语”">​</a></h2><h3 id="frontmatter" tabindex="-1">Frontmatter <a class="header-anchor" href="#frontmatter" aria-label="Permalink to “Frontmatter”">​</a></h3><ul><li><strong>定义</strong>: Markdown 文件开头的 YAML 格式元数据区块</li><li><strong>格式</strong>: 使用 <code>---</code> 包裹，包含 <code>title</code>、<code>description</code> 等字段</li><li><strong>示例</strong>:<div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes vitesse-light vitesse-dark" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">---</span></span>
<span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">title</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> 快速上手</span></span>
<span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">description</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> Dora Pocket 的入门指南</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">---</span></span></code></pre></div></li></ul><h3 id="vitepress" tabindex="-1">VitePress <a class="header-anchor" href="#vitepress" aria-label="Permalink to “VitePress”">​</a></h3><ul><li><strong>定义</strong>: 本项目使用的静态文档网站生成器</li><li><strong>技术栈</strong>: 基于 Vite 和 Vue 3</li><li><strong>配置文件</strong>: <code>docs/.vitepress/config.ts</code></li><li><strong>特点</strong>: 支持 Markdown、Vue 组件和自定义主题</li></ul><h3 id="kit" tabindex="-1">Kit <a class="header-anchor" href="#kit" aria-label="Permalink to “Kit”">​</a></h3><ul><li><strong>定义</strong>: <code>@esdora/kit</code> 包的简称，提供通用工具函数</li><li><strong>全称</strong>: <code>@esdora/kit</code></li><li><strong>特点</strong>: 零依赖、类型安全、纯函数式</li><li><strong>文档位置</strong>: <code>docs/packages/kit/</code></li></ul><h3 id="module-模块" tabindex="-1">Module (模块) <a class="header-anchor" href="#module-模块" aria-label="Permalink to “Module (模块)”">​</a></h3><ul><li><strong>定义</strong>: 项目中的独立功能包</li><li><strong>命名规范</strong>: 使用 <code>@esdora/[name]</code> 格式</li><li><strong>示例</strong>: <code>@esdora/kit</code>, <code>@esdora/color</code>, <code>@esdora/date</code></li><li><strong>组织方式</strong>: Monorepo 结构，使用 pnpm workspace</li></ul><h3 id="package-包" tabindex="-1">Package (包) <a class="header-anchor" href="#package-包" aria-label="Permalink to “Package (包)”">​</a></h3><ul><li><strong>定义</strong>: 可独立发布和安装的 npm 包</li><li><strong>关系</strong>: 与 Module 同义，在本项目中可互换使用</li><li><strong>管理工具</strong>: pnpm (workspace)</li></ul><h3 id="monorepo" tabindex="-1">Monorepo <a class="header-anchor" href="#monorepo" aria-label="Permalink to “Monorepo”">​</a></h3><ul><li><strong>定义</strong>: 单一代码仓库管理多个包的项目结构</li><li><strong>工具</strong>: pnpm workspace + Turbo</li><li><strong>优势</strong>: 代码共享、统一版本管理、简化开发流程</li></ul><h3 id="typescript" tabindex="-1">TypeScript <a class="header-anchor" href="#typescript" aria-label="Permalink to “TypeScript”">​</a></h3><ul><li><strong>定义</strong>: JavaScript 的超集，提供静态类型系统</li><li><strong>版本</strong>: 使用 ESNext 目标</li><li><strong>配置</strong>: <code>tsconfig.json</code></li><li><strong>构建工具</strong>: tsdown</li></ul><h3 id="vitest" tabindex="-1">Vitest <a class="header-anchor" href="#vitest" aria-label="Permalink to “Vitest”">​</a></h3><ul><li><strong>定义</strong>: 本项目使用的单元测试框架</li><li><strong>特点</strong>: 基于 Vite，与 Jest 兼容的 API</li><li><strong>用途</strong>: 编写和运行函数测试，测试代码用于文档生成</li></ul><h3 id="示例驱动-example-driven" tabindex="-1">示例驱动 (Example-Driven) <a class="header-anchor" href="#示例驱动-example-driven" aria-label="Permalink to “示例驱动 (Example-Driven)”">​</a></h3><ul><li><strong>定义</strong>: 文档编写哲学，强调使用丰富的代码示例来阐述功能</li><li><strong>原则</strong>: &quot;一个好的示例胜过千言万语&quot;</li><li><strong>实践</strong>: 每个函数文档都包含多个实际使用场景的示例</li></ul><h3 id="用户中心-user-centric" tabindex="-1">用户中心 (User-Centric) <a class="header-anchor" href="#用户中心-user-centric" aria-label="Permalink to “用户中心 (User-Centric)”">​</a></h3><ul><li><strong>定义</strong>: 文档编写的核心原则，始终站在使用者角度思考</li><li><strong>目标</strong>: 解决用户的实际问题，而非展示技术实现</li><li><strong>体现</strong>: 清晰的描述、实用的示例、完善的边界情况说明</li></ul><h2 id="文档元数据字段" tabindex="-1">文档元数据字段 <a class="header-anchor" href="#文档元数据字段" aria-label="Permalink to “文档元数据字段”">​</a></h2><h3 id="title-必需" tabindex="-1">title (必需) <a class="header-anchor" href="#title-必需" aria-label="Permalink to “title (必需)”">​</a></h3><ul><li><strong>定义</strong>: 文档页面的标题</li><li><strong>类型</strong>: 字符串</li><li><strong>规范</strong>: 应简短明确，准确反映页面内容</li><li><strong>示例</strong>: <code>&quot;快速上手&quot;</code>, <code>&quot;isCircular&quot;</code>, <code>&quot;toHex&quot;</code></li><li><strong>使用位置</strong>: Frontmatter 的 <code>title</code> 字段</li></ul><h3 id="description-必需" tabindex="-1">description (必需) <a class="header-anchor" href="#description-必需" aria-label="Permalink to “description (必需)”">​</a></h3><ul><li><strong>定义</strong>: 文档页面的详细描述</li><li><strong>类型</strong>: 字符串</li><li><strong>规范</strong>: 应包含完整的功能说明，包括来源和用途</li><li><strong>格式</strong>: 对于函数文档，使用 <code>&quot;[函数名] - 来自 Dora Pocket 的[类别]&quot;道具&quot;，用于[功能描述]。&quot;</code></li><li><strong>示例</strong>: <code>&quot;toHex - 来自 Dora Pocket 的颜色&quot;道具&quot;，用于将任意颜色格式转换为十六进制 (HEX) 字符串。&quot;</code></li><li><strong>使用位置</strong>: Frontmatter 的 <code>description</code> 字段</li></ul><h3 id="category-可选" tabindex="-1">category (可选) <a class="header-anchor" href="#category-可选" aria-label="Permalink to “category (可选)”">​</a></h3><ul><li><strong>定义</strong>: 文档的分类标签</li><li><strong>类型</strong>: 枚举值</li><li><strong>可选值</strong>: <code>API</code> | <code>架构</code> | <code>指南</code> | <code>实践</code> | <code>贡献</code></li><li><strong>用途</strong>: 用于文档分类和导航生成</li><li><strong>示例</strong>: <code>category: &quot;API&quot;</code></li><li><strong>使用位置</strong>: Frontmatter 的 <code>category</code> 字段（扩展字段）</li></ul><h3 id="ai-model-可选" tabindex="-1">ai_model (可选) <a class="header-anchor" href="#ai-model-可选" aria-label="Permalink to “ai_model (可选)”">​</a></h3><ul><li><strong>定义</strong>: 生成该文档时使用的 AI 模型</li><li><strong>类型</strong>: 枚举值</li><li><strong>可选值</strong>: <code>Codex</code> | <code>Gemini</code> | <code>Qwen</code></li><li><strong>用途</strong>: 标记文档生成方式，便于质量追踪和优化</li><li><strong>示例</strong>: <code>ai_model: &quot;Gemini&quot;</code></li><li><strong>使用位置</strong>: Frontmatter 的 <code>ai_model</code> 字段（扩展字段）</li></ul><h2 id="相关资源" tabindex="-1">相关资源 <a class="header-anchor" href="#相关资源" aria-label="Permalink to “相关资源”">​</a></h2><ul><li><a href="./">文档规范系统概览</a></li><li><a href="./api-template">API 文档模板</a></li><li><a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress 官方文档</a></li></ul>`,54)])])}const u=o(a,[["render",l]]);export{p as __pageData,u as default};
